css:
.lsm-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.lsm-root,.lsm-root *,.lsm-root *::before,.lsm-root *::after{box-sizing:border-box}
.lsm-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.lsm-root img{display:block;border:0;max-width:none}
.lsm-root [hidden]{display:none!important}
.lsm-root .n30_299{grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;place-items:start;position:relative;flex-shrink:0}
.lsm-root .n30_300{grid-column:1;grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;margin-left:0;margin-top:15px;place-items:start;position:relative;grid-row:1}
.lsm-root .n30_301{grid-column:1;height:71.982px;margin-left:0;margin-top:0;position:relative;grid-row:1;width:254px}
.lsm-root .x84{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lsm-root .n30_302{word-break:break-word;grid-column:1;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:24px;margin-left:96px;margin-top:27px;font-style:normal;position:relative;grid-row:1;color:var(--wa-point, #98c4ff);font-size:20px;text-align:center;width:60.994px;white-space:nowrap}
.lsm-root .n30_303{grid-column:1;align-content:stretch;display:flex;gap:7px;height:30px;align-items:center;margin-left:0.01px;margin-top:0;padding-right:15px;position:relative;border-radius:8px;grid-row:1;width:93.991px;background-image:linear-gradient(to bottom,color-mix(in srgb, var(--wa-point, rgb(32 74 194)) 90%, transparent),color-mix(in srgb, var(--wa-point, rgb(21 27 57)) 90%, transparent) 51%,color-mix(in srgb, var(--wa-point, rgb(32 74 194)) 90%, transparent))}
.lsm-root .n30_304{align-content:stretch;display:flex;align-items:flex-start;padding:7px;position:relative;border-radius:8px;flex-shrink:0;width:30px;height:30px}
.lsm-root .x85{position:absolute;background-color:var(--wa-point, #303860);inset:0;pointer-events:none;border-radius:8px}
.lsm-root .n30_305{position:relative;flex-shrink:0;width:16px;height:16px}
.lsm-root .x86{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.lsm-root .x87{position:absolute;inset:0;pointer-events:none;border-radius:inherit;box-shadow:inset 0px 0px 6px 0px #7bbbfc}
.lsm-root .n30_307{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:19px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-point, #c6d4fa);font-size:16px;white-space:nowrap;width:42px}
.lsm-root [data-name="Widget/Sensor Status"] > * > *{margin-left:0;margin-top:0}
.lsm-root [data-node-id$=";13:354"]{border-image:linear-gradient(to bottom,var(--wa-line, #fff) 60%,var(--wa-point, #7cccff) 60%) 1}
.lsm-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.lsm-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.lsm-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.lsm-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.lsm-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.lsm-root[data-theme="light"] .n30_303{background-image:linear-gradient(to bottom,color-mix(in srgb, var(--wa-point, rgb(32 74 194)) 90%, transparent),color-mix(in srgb, var(--wa-surface, rgb(200 203 220)) 90%, transparent) 51%,color-mix(in srgb, var(--wa-point, rgb(32 74 194)) 90%, transparent))}
.lsm-root[data-theme="light"] .x85{background-color:var(--wa-surface, #b7bbcc)}
.lsm-root[data-theme="light"] .n30_307{color:var(--wa-point, #0e359f)}
